// Fictional sample portraits and two-digit suffixes. Replace each intake's
// array with approved student records. A real portrait uses image: 'assets/...'.
// Full student numbers and personal details are not needed by the directory.
const sampleNames = ['آرمان نیک‌پی','رها کیانی','نیما فرهمند','سارا امینی','پارسا مهران','نگار راد','مهسا فرزان','کیان نوری','یلدا نیک‌روش','سامان مهر','آوا شایان','علی سامان','پویا خردمند','درسا مهرآیین','مانی روشن','پرنیان صدر','آرش کاظمی','نیکا سروش','هستی شاهین','امیر رادمنش','ترانه آزاد','دانیال پارسافر','شیدا ناصری','بردیا نیکزاد','مهراد آیین','یلدا مهرآرا','روزبه شریفی','نازنین خسروی','سام فرزاد','مهتاب مهر'];
const sampleMoments = ['اولین روز ورود به دانشکده و پیدا کردن آتلیه','ساعت‌های آرام کتابخانه و ورق زدن کتاب‌های معماری','ساختن اولین ماکت در کنار دوستانم','قدم زدن در محوطه بعد از یک تحویل طولانی','بحث‌های پرشور درباره یک طرح ساده','نور صبحگاهی که روی میزهای آتلیه می‌افتاد','همکاری گروهی برای آماده کردن یک ارائه','طرح‌هایی که بارها پاک شدند و دوباره شکل گرفتند','تماشای تغییر فصل‌ها از پنجره دانشکده','لحظه‌ای که برای نخستین بار طرحم را توضیح دادم'];
function sampleMemory(index) {
  return [
    `وقتی به سال‌های دانشگاه فکر می‌کنم، ${sampleMoments[index % sampleMoments.length]} زودتر از هر تصویر دیگری به یادم می‌آید. دانشگاه شهید بهشتی برای من مجموعه‌ای از کلاس‌ها و ساختمان‌ها نبود؛ جایی بود که یاد گرفتم با دقت بیشتری به آدم‌ها، فضاها و زندگی نگاه کنم. آن روزها هنوز نمی‌دانستم مسیر معماری چقدر با تجربه کردن، پرسیدن و دوباره شروع کردن گره خورده است. هر تمرین کوچک فرصتی بود تا چیزی از خودم کشف کنم و جسارت بیان یک فکر تازه را پیدا کنم.`,
    'در آتلیه، زمان معنای دیگری داشت. گاهی ساعت‌ها بر سر جای یک دیوار، مسیر نور یا نسبت دو حجم گفت‌وگو می‌کردیم و در پایان می‌فهمیدیم پرسش اصلی جای دیگری بوده است. کنار میزهای شلوغ، میان کاغذهای کالک و تکه‌های ماکت، دوستی‌هایی شکل گرفت که از هر نمره و تحویلی ماندگارتر شد. کمک ساده یک همکلاسی در آخرین ساعت، نقد صادقانه یک استاد و خنده‌های کوتاه میان خستگی، بخش بزرگی از خاطره من از این دوره هستند.',
    'دانشگاه به من آموخت معماری پیش از آنکه ساختن یک بنا باشد، توجه کردن به زندگی انسان‌هاست. یاد گرفتم برای هر تصمیم دلیل داشته باشم، دیدگاه دیگران را بشنوم و از تغییر دادن طرحم نترسم. روزهایی هم بود که نتیجه مطابق انتظار پیش نمی‌رفت، اما همان روزها صبر و مسئولیت‌پذیری را بهتر شناختم. حالا می‌دانم بخش ارزشمند این مسیر، فقط پروژه‌های نهایی نبود؛ رشد آرامی بود که در جریان کار جمعی و تلاش روزانه اتفاق افتاد.',
    'این چند خط را می‌گذارم تا سال‌ها بعد، وقتی دوباره به این صفحه برگشتم، یادم بماند از کجا شروع کردم و چه کسانی در این راه کنارم بودند. برای دوستانم آرزو می‌کنم در هر مسیری که انتخاب می‌کنند، کنجکاوی و مهربانی آن سال‌ها را حفظ کنند. از استادان و همه کسانی که فرصت یاد گرفتن را فراهم کردند سپاسگزارم. امیدوارم سهم کوچک ما در معماری آینده، ساختن فضاهایی باشد که آدم‌ها در آن احساس تعلق کنند؛ همان احساسی که در بهترین لحظه‌های دانشگاه تجربه کردیم.'
  ];
}
window.MELLI_STUDENTS = Object.fromEntries((window.MELLI_COHORTS || []).map(cohort => [
  cohort.year,
  Array.from({length: 30}, (_, index) => ({
    name: sampleNames[index],
    memory: sampleMemory(index),
    studentSuffix: String(index + 1).padStart(2, '0'),
    sample: true,
    image: index === 0 ? 'assets/graduate-male-approved.png' : index === 1 ? 'assets/graduate-female-approved.png' : undefined,
    portraitAtlas: 'assets/graduate-portraits-approved-atlas.png',
    portraitAtlasAspect: 0.9,
    portraitIndex: index,
    portraitColumns: 6,
    portraitRows: 5
  }))
]));
